        function saveConfigs()
            pcall(function()
                local c = writefile or make_writefile or (syn and syn.writefile)
                if not c then
                    return
                end
                local d = { activeProfile = profileStore.activeProfile, profiles = {} }
                for c, f in pairs(profileStore.profiles) do
                    d.profiles[c] = serializeTable(f)
                end
                c(configsFile, (game:GetService("HttpService")):JSONEncode(d))
            end)
        end
        function loadConfigs()
            profileStore.profiles.Default = serializeTable(settings)
            local c = readfile or make_readfile or (syn and syn.readfile)
            local d = isfile or (syn and syn.isfile)
            if c then
                if d and d(configsFile) then
                    pcall(function()
                        local d = c(configsFile)
                        if d and d ~= "" then
                            local c = (game:GetService("HttpService")):JSONDecode(d)
                            if c and c.profiles then
                                profileStore.activeProfile = c.activeProfile or "Default"
                                for c, d in pairs(c.profiles) do
                                    local f = {}
                                    deserializeTable(f, serializeTable(settings))
                                    deserializeTable(f, d)
                                    profileStore.profiles[c] = f
                                end
                            end
                        end
                    end)
                elseif d and d(settingsFile) then
                    pcall(function()
                        local d = c(settingsFile)
                        if d and d ~= "" then
                            local c = (game:GetService("HttpService")):JSONDecode(d)
                            if c then
                                local d = {}
                                deserializeTable(d, serializeTable(settings))
                                deserializeTable(d, c)
                                profileStore.profiles.Default = d
                                saveConfigs()
                            end
                        end
                    end)
                end
            end
