                        if _G.VD_FarmState.lastKillerRoundScanned ~= _G.VD_FarmState.lastKillerSpawnTime then
                            _G.VD_FarmState.lastKillerRoundScanned = _G.VD_FarmState.lastKillerSpawnTime
