        function isSurvivorFarmAllowed()
            if not settings.AutoFarmSurvivor then
                return false
            end
            local c = localPlayer.Team and localPlayer.Team.Name or ""
            if c ~= "Survivors" then
                return false
            end
            if settings.AutoFarmAFKTotal then
                if (_G.VD_FarmState.lastSurvivorSpawnTime or 0) == 0 then
                    return false
                end
                local c = tick() - (_G.VD_FarmState.lastSurvivorSpawnTime or 0)
                if c < 15 then
                    return false
                end
            end
            local d = localPlayer.Character
            local f = d and (getModelAttribute(d, "Knocked") == true or d:GetAttribute("Knocked") == true)
            local g = d and (getModelAttribute(d, "IsHooked") == true or d:GetAttribute("IsHooked") == true)
            if f or g then
                return false
            end
            return true
        end
