            local f = c:FindFirstChild("SelectedKiller")
            if f and (f:IsA("StringValue") or f:IsA("ValueObject")) then
                return tostring(f.Value)
            end
            if c.Character then
                local d = c.Character:GetAttribute("SelectedKiller")
                if d ~= nil then
