        function getGeneratorProgress(c)
            local d = c:GetAttribute("RepairProgress")
            if d == nil then
                local f = c:FindFirstChild("RepairProgress")
                if f and f:IsA("ValueObject") then
                    d = f.Value
                end
            end
            if not d then
                return 0
            end
            local f = tonumber(d)
            if f then
                if f <= 1.01 and f > 0 then
                    return math.round(f * 100)
                else
                    return math.round(f)
                end
            end
            return 0
        end
        local genAnalyticsCache = {}
        function isGeneratorRegressing(c)
            if not c then
                return false
            end
            local d = c:GetAttribute("Regressing")
            if d ~= nil then
                return d == true
            end
            local f, g = pcall(function()
                local d = c:FindFirstChild("Regressing")
                if d then
                    if d:IsA("ValueObject") or d:IsA("BoolValue") then
                        return d.Value == true
                    end
                    return true
                end
                return c.Regressing == true
            end)
            if f and g == true then
                return true
            end
            local h = c:FindFirstChild("HitBox")
                or c:FindFirstChild("Hitbox")
                or c:FindFirstChild("Engine")
                or c.PrimaryPart
            if h then
                local c = h:GetAttribute("Regressing")
                if c == true then
                    return true
                end
                local d = h:FindFirstChild("Regressing")
                if d then
                    if d:IsA("ValueObject") or d:IsA("BoolValue") then
                        return d.Value == true
                    end
                    return true
                end
            end
            return false
        end
        function getGeneratorAnalytics(c)
            if not c then
                return 0, nil, ""
            end
            local d = genAnalyticsCache[c]
            if not d then
                return 0, nil, ""
            end
            return d.smoothedSpeed or 0, d.etaSeconds, d.etaFormatted or ""
        end
        local function updateGeneratorAlerts()
            local c = tick()
            local d = settings.MasterESP
                and (
                    settings.GeneratorESP
                    and (settings.GeneratorESP.Enabled and settings.GeneratorESP.AlertThresholdEnabled)
                )
            local f = (settings.GeneratorESP and settings.GeneratorESP.AlertThreshold) or 90
            for g, h in ipairs(cachedGenerators or {}) do
                if not h or not h.Parent then
                    continue
                end
                if isGeneratorCompleted(h) then
                    genAnalyticsCache[h] = nil
                    continue
                end
                local i = getGeneratorProgress(h)
                local j = genAnalyticsCache[h]
                if not j then
                    genAnalyticsCache[h] = {
                        lastProgress = i,
                        lastTime = c,
                        history = {},
                        smoothedSpeed = 0,
                        smoothedETA = nil,
                        etaSeconds = nil,
                        etaFormatted = "",
                        alertTriggered = (i >= f),
                    }
                    continue
                end
                local k = c - j.lastTime
                if k >= 0.75 then
                    local g = i - j.lastProgress
                    local l = isGeneratorRegressing(h)
                    local m = 0
                    if g ~= 0 then
                        m = g / k
                    elseif l then
                        if j.smoothedSpeed and j.smoothedSpeed < 0 then
                            m = j.smoothedSpeed
                        else
                            m = -0.5
                        end
                    else
                        m = 0
                    end
                    table.insert(j.history, m)
                    if #j.history > 5 then
                        table.remove(j.history, 1)
                    end
                    local n = 0
                    for c, d in ipairs(j.history) do
                        n = n + d
                    end
                    local o = n / #j.history
                    local p = j.smoothedSpeed or 0
                    local q = p + (o - p) * 0.25
                    if math.abs(q) < 0.05 then
                        q = 0
                    end
                    local r = nil
                    local s = ""
                    if q > 0.1 then
                        local c = 100 - i
                        local d = math.max(0, c / q)
                        local f = j.smoothedETA or d
                        local g = f + (d - f) * 0.2
                        j.smoothedETA = g
                        r = g
                        if r < 60 then
                            s = string.format("%ds", math.ceil(r))
                        else
                            local c = math.floor(r / 60)
                            local d = math.ceil(r % 60)
                            s = string.format("%dm %02ds", c, d)
                        end
                    else
                        j.smoothedETA = nil
                    end
                    j.smoothedSpeed = q
                    j.etaSeconds = r
                    j.etaFormatted = s
                    j.lastProgress = i
                    j.lastTime = c
                    if d then
                        if i >= f then
                            if not j.alertTriggered then
                                j.alertTriggered = true
