        function getMapName()
            local c, d = pcall(function()
                return (game:GetService("Players")).LocalPlayer.PlayerGui.Darkness.Frame.MapInfo.MapTitle.Text
            end)
            if c and (d and d ~= "") then
                if d:upper() == "NOSTROMO" then
                    return "Loading..."
                end
                return d
            end
            local f = workspace:FindFirstChild("Map")
            if not f then
                lastMapModel = nil
                currentMapName = "Unknown Map"
                return currentMapName
            end
            local g = f:FindFirstChildOfClass("Model") or f:FindFirstChildOfClass("Folder") or f
            if g == lastMapModel and currentMapName ~= "Unknown Map" then
                return currentMapName
            end
            lastMapModel = g
            if f:FindFirstChild("HooksMeat", true) then
                currentMapName = "BLOODBATH! Club"
                return currentMapName
            end
            if f:FindFirstChild("Rooftop", true) then
                currentMapName = "Mercy Hospital Rooftop"
                return currentMapName
            end
            if f:FindFirstChild("inviswallasylum", true) then
                currentMapName = "Mount Massive Asylum"
                return currentMapName
            end
            if f:FindFirstChild("Tesla", true) then
                currentMapName = "Site 68"
                return currentMapName
            end
            if f:FindFirstChild("Breakwater", true) then
                currentMapName = "The Bay Harbor"
                return currentMapName
            end
            if f:FindFirstChild("RockVar0", true) then
                currentMapName = "Woodview Cabin"
                return currentMapName
            end
            local h = f:FindFirstChild("Model", true)
            if h then
                local c = (h:GetPivot()).Position
                if ((c - Vector3.new(-811.4, 212.8, -7774.5))).Magnitude < 100 then
                    currentMapName = "Firelink Shrine"
                    return currentMapName
                end
                if ((c - Vector3.new(1114.67, -16.92, -12.99))).Magnitude < 100 then
                    currentMapName = "Valdelobos Village"
                    return currentMapName
                end
            end
            currentMapName = "Unknown Map"
            return currentMapName
        end
