        function manageHighlights()
            local c = {}
            for d, f in pairs(ActiveESP.Players) do
                if f.Highlight and f.LastAuraEnabled then
                    table.insert(
                        c,
                        { data = f, priority = 1, dist = getDistance(d, f.Billboard and f.Billboard.Adornee) }
                    )
                else
                    f.TargetHighlightVisible = false
                end
            end
            local d = {
                ActiveESP.SCPs,
                ActiveESP.Generators,
                ActiveESP.Hooks,
                ActiveESP.Pallets,
                ActiveESP.Vaults,
                ActiveESP.BloodEffects,
                ActiveESP.Gates,
            }
            for d, f in ipairs(d) do
                local g = 4
                if d == 1 then
                    g = 2
                elseif d == 2 or d == 7 then
                    g = 3
                end
                for d, f in pairs(f) do
                    if f.Highlight and f.LastAuraEnabled then
                        table.insert(c, { data = f, priority = g, dist = getDistance(d, f.LastBillboardAdornee) })
                    else
                        f.TargetHighlightVisible = false
                    end
                end
            end
            table.sort(c, function(c, d)
                if c.priority ~= d.priority then
                    return c.priority < d.priority
                end
                return c.dist < d.dist
            end)
            local f = 28
            for c, d in ipairs(c) do
                local g = (c <= f)
                d.data.TargetHighlightVisible = g
                if (settings.ESPFadeDuration or 0.2) <= 0.01 then
                    if d.data.Highlight:IsA("Highlight") then
                        if d.data.Highlight.Enabled ~= g then
                            d.data.Highlight.Enabled = g
                        end
                    elseif d.data.Highlight:IsA("BoxHandleAdornment") then
                        if d.data.Highlight.Visible ~= g then
                            d.data.Highlight.Visible = g
                        end
                    end
                    if d.data.PuddleHighlight and d.data.PuddleHighlight:IsA("Highlight") then
                        if d.data.PuddleHighlight.Enabled ~= g then
                            d.data.PuddleHighlight.Enabled = g
                        end
                    end
                end
            end
        end
        function updateESPFadeTransitions(c)
            local d = settings.ESPFadeDuration or 0.2
            local f = (d <= 0.01)
            local g = settings.ESPFillTransparency or 0.6
            local h = settings.ESPOutlineTransparency or 0.1
            local function i(i, j)
                if not i or not i.Highlight then
                    return
                end
                local k = 0
                if i.TargetHighlightVisible ~= false and i.LastAuraEnabled then
                    k = i.DistanceOpacityFactor or 1
                end
                if i.CurrentAlpha == nil then
                    i.CurrentAlpha = k
                elseif f then
                    i.CurrentAlpha = k
                else
                    local f = c / d
                    if i.CurrentAlpha < k then
                        i.CurrentAlpha = math.min(k, i.CurrentAlpha + f)
                    elseif i.CurrentAlpha > k then
                        i.CurrentAlpha = math.max(k, i.CurrentAlpha - f)
                    end
                end
                local l = i.CurrentAlpha
                local m = l > 0.005
                if j then
                    if i.Highlight:IsA("BoxHandleAdornment") then
                        if i.Highlight.Visible ~= m then
                            i.Highlight.Visible = m
                        end
                        if m then
                            i.Highlight.Transparency = 1 - ((1 - g) * l)
                        end
                    end
                else
                    if i.Highlight:IsA("Highlight") then
                        if i.Highlight.Enabled ~= m then
                            i.Highlight.Enabled = m
                        end
                        if m then
                            i.Highlight.FillTransparency = 1 - ((1 - g) * l)
                            i.Highlight.OutlineTransparency = 1 - ((1 - h) * l)
                        end
                    end
                    if i.PuddleHighlight and i.PuddleHighlight:IsA("Highlight") then
                        if i.PuddleHighlight.Enabled ~= m then
                            i.PuddleHighlight.Enabled = m
                        end
                        if m then
                            i.PuddleHighlight.FillTransparency = 1 - ((1 - g) * l)
                            i.PuddleHighlight.OutlineTransparency = 1 - ((1 - h) * l)
                        end
                    end
                end
            end
            for c, d in pairs(ActiveESP.Players) do
                i(d, false)
            end
            for c, d in pairs({
                ActiveESP.Generators,
                ActiveESP.Hooks,
                ActiveESP.Pallets,
                ActiveESP.BloodEffects,
                ActiveESP.Gates,
                ActiveESP.SCPs,
            }) do
                for a, b in pairs(d) do
                    i(b, false)
                end
            end
            for a, b in pairs(ActiveESP.Vaults) do
                i(b, true)
            end
        end
