        function applyTheme(d)
            currentThemeName = d or "Default"
            local f = themes[currentThemeName] or themes.Default
            local g = UI.Bg
            local h = UI.Sidebar
            local i = UI.Card
            local j = UI.Elevated
            local k = UI.Stroke
            local l = UI.StrokeDim
            local m = UI.Accent
