                )
            mainFrame.BackgroundTransparency = r and 1 or f.BgTrans
            local s = mainFrame:FindFirstChildOfClass("UIStroke")
            if s then
                s.Color = UI.Stroke
                s.Thickness = 1
            end
            local t = mainFrame:FindFirstChild("Sidebar")
            if t then
                t.BackgroundColor3 = UI.Sidebar
                t.BackgroundTransparency = r and 0.85 or f.BgTrans
                local c = t:FindFirstChildOfClass("UIStroke")
                if c then
                    c.Color = UI.StrokeDim
