                        or (customBgImage and d == customBgImage)
                        or (customBgOverlay and d == customBgOverlay)
                    then
                        if d.Name == "VD_CustomBg" or (customBgImage and d == customBgImage) then
                            pcall(function()
                                d.ImageColor3 = Color3.fromRGB(255, 255, 255)
                            end)
                        end
                        continue
                    end
                    local c = d.Name
                    local f = c:lower()
                    local q = (c == "LogoImage" or f:find("logo") ~= nil or c == "TitleLogo")
                        or (c == "HomeHeaderAvatar" or c == "WelcomeBackAvatar" or f:find("avatar") ~= nil or f:find(
                            "portrait"
                        ) ~= nil or f:find("survivor") ~= nil)
                        or (
                            d:IsA("ImageLabel")
                            and (
                                d.Image
                                and (
                                    d.Image:find("rbxthumb://") ~= nil
                                    or d.Image:find("roblox.com") ~= nil
                                    or d.Image:find("dbd_hud_") ~= nil
                                    or d.Image:find("VD_Logo") ~= nil
                                )
                            )
                        )
                    if q then
                        if d:IsA("ImageLabel") or d:IsA("ImageButton") then
                            d.ImageColor3 = Color3.fromRGB(255, 255, 255)
                        elseif d:IsA("TextLabel") and c == "TitleLogo" then
                            d.TextColor3 = UI.Text
                        end
                        local f = d:FindFirstChildOfClass("UIStroke")
                        if f then
                            f.Color = UI.Accent
                        end
                        continue
                    end
                    if d.BackgroundColor3 == g then
                        d.BackgroundColor3 = UI.Bg
                    elseif d.BackgroundColor3 == h then
                        d.BackgroundColor3 = UI.Sidebar
                    elseif d.BackgroundColor3 == i then
                        d.BackgroundColor3 = UI.Card
                    elseif d.BackgroundColor3 == j then
                        d.BackgroundColor3 = UI.Elevated
                    elseif d.BackgroundColor3 == m then
                        d.BackgroundColor3 = UI.Accent
                    elseif d.BackgroundColor3 == n then
                        d.BackgroundColor3 = UI.AccentCyan
                    elseif d.BackgroundColor3 == o then
                        d.BackgroundColor3 = UI.AccentGreen
                    elseif d.BackgroundColor3 == p then
                        d.BackgroundColor3 = UI.AccentRed
                    elseif d.BackgroundColor3 == k then
                        d.BackgroundColor3 = UI.Stroke
                    elseif d.BackgroundColor3 == l then
                        d.BackgroundColor3 = UI.StrokeDim
                    end
                    if d:IsA("ImageLabel") or d:IsA("ImageButton") then
                        local f = c == "TabIcon"
                            or c == "Icon"
                            or c == "SearchIcon"
                            or c:find("Chevron") ~= nil
                            or c:find("Check") ~= nil
                            or (
                                d.Parent
                                and (
                                    d.Parent.Name:find("TabBtn") ~= nil
                                    or d.Parent.Name:find("Toggle") ~= nil
                                    or d.Parent.Name:find("Selector") ~= nil
                                    or d.Parent.Name:find("Slider") ~= nil
                                )
                            )
                        if f then
                            if d.ImageColor3 == m then
                                d.ImageColor3 = UI.Accent
                            elseif d.ImageColor3 == n then
                                d.ImageColor3 = UI.AccentCyan
                            elseif d.ImageColor3 == k then
                                d.ImageColor3 = UI.Stroke
                            elseif d.ImageColor3 == l then
                                d.ImageColor3 = UI.StrokeDim
                            end
                        end
                    end
                    if d:IsA("TextLabel") or d:IsA("TextBox") or d:IsA("TextButton") then
                        local f = d:GetAttribute("ThemeAccentText") == true
                            or c == "PopupTitle"
                            or c == "GetKeyBtn"
                            or (d.Parent and d.Parent.Name == "HeaderBanner")
                            or (d.Parent and d.Parent.Name:find("MobileFloating_") ~= nil)
                        if f then
                            if d.TextColor3 == m then
