                local c = (searchBox.Text:gsub("^%s*(.-)%s*$", "")):lower()
                if #c > 0 then
                    pcall(updateSearchResults, c)
                end
            end
            if applyCustomBackground then
                pcall(applyCustomBackground)
            elseif _G.VD_ApplyCustomBg then
                pcall(_G.VD_ApplyCustomBg)
            end
        end
        local nodePositionCache = {}
        local function slugifyName(c)
            if not c or c == "" then
                return nil
            end
            local d = ((tostring(c)):lower()):gsub("%s+", "")
            if d == "togglespeedboost" or d == "speedboost" then
                return settings.SpeedBoostEnabled == true
            elseif d == "noturnspeedloss" or d == "preserveturnspeed" then
                return settings.NoTurnSpeedLoss == true
            elseif d == "automoonwalk" or d == "moonwalk" then
                return settings.AutoMoonwalk == true
            elseif d == "noclipvaultspallets" or d == "noclip" then
                return settings.NoclipVaultsPallets == true
            elseif d == "autofleekiller" or d == "autoflee" then
                return settings.AutoFleeKiller == true
            elseif d == "alwaysfastvault" or d == "fastvault" then
                return settings.AlwaysFastVault == true
            elseif d == "instantheal" then
                return settings.InstantHeal == true
            elseif d == "autoparry" then
                return settings.AutoParry == true
            elseif d == "frenzyparry" then
                return settings.FrenzyParry == true
            elseif d == "revolverautofarm" then
                return settings.RevolverAutofarm == true
            elseif d == "revolveraimbot" or d == "aimbot" then
                return (settings.RevolverAimbot and settings.RevolverAimbot.Enabled) == true
            elseif d == "flowstateperk" or d == "flowstate" then
                return settings.FlowstatePerk == true
            elseif d == "activefeaturesoverlay" or d == "activefeatures" then
                return settings.ShowActiveFeatures == true
            elseif d == "spectatorlist" or d == "spectators" then
                return settings.ShowSpectatorList == true
            elseif d == "nofog" then
                return settings.NoFog == true
            elseif d == "dofremoval" or d == "removedof" then
                return settings.RemoveDOF == true
            elseif d == "fullbright" then
                return settings.FullBright == true
            elseif d == "noskillchecks" then
                return settings.NoSkillChecks == true
            elseif d == "rainbowcharacter" or d == "rainbow" then
                return settings.RainbowCharacter == true
            elseif d == "fakelag" then
                return settings.FakeLag == true
            elseif d == "desync" then
                return settings.Desync == true
            elseif d == "blockvaultpalletinteraction" or d == "blockvaults" or d == "blockpallets" then
                return settings.BlockVaultPalletInteraction == true
            elseif settings[c] ~= nil and type(settings[c]) == "boolean" then
                return settings[c] == true
            end
            for c, f in pairs(settings) do
                if type(f) == "boolean" then
                    local g = (c:lower()):gsub("%s+", "")
                    if g == d then
                        return f == true
                    end
                end
            end
            return nil
        end
