        function switchTab(c)
            if activeTab == c and (not searchContainer or not searchContainer.Visible) then
                if tabContainers and (tabContainers[c] and not tabContainers[c].Visible) then
                    tabContainers[c].Visible = true
                    tabContainers[c].GroupTransparency = 0
                end
                return
            end
            if searchContainer then
                searchContainer.Visible = false
            end
            if searchBox and searchBox.Text ~= "" then
                searchBox.Text = ""
                if clearSearchBtn then
                    clearSearchBtn.Visible = false
                end
            end
            for d, f in pairs(tabButtons) do
                local g = f:FindFirstChild("Icon")
                local h = f:FindFirstChild("ActiveIndicator")
                local i = f:FindFirstChildOfClass("UIStroke")
                if d == c then
                    (TweenService:Create(
                        f,
                        TweenInfo.new(0.18),
                        { BackgroundColor3 = Color3.fromRGB(18, 20, 26), BackgroundTransparency = 0.1 }
                    )):Play()
                    if i then
                        (TweenService:Create(
                            i,
                            TweenInfo.new(0.18),
                            { Transparency = 0, Color = Color3.fromRGB(255, 255, 255) }
                        )):Play()
                    end
                    if g then
                        (TweenService:Create(
                            g,
                            TweenInfo.new(0.18),
                            { ImageColor3 = Color3.fromRGB(255, 255, 255), ImageTransparency = 0 }
                        )):Play()
                    end
                    if h then
                        (TweenService:Create(
                            h,
                            TweenInfo.new(0.18),
                            { BackgroundTransparency = 0, Size = UDim2.new(0, 3, 0.7, 0) }
                        )):Play()
                    end
                else
                    (TweenService:Create(
                        f,
                        TweenInfo.new(0.18),
                        { BackgroundColor3 = Color3.fromRGB(15, 16, 21), BackgroundTransparency = 1 }
                    )):Play()
