                        (TweenService:Create(i, TweenInfo.new(0.18), { Transparency = 1 })):Play()
                    end
                    if g then
                        (TweenService:Create(
                            g,
                            TweenInfo.new(0.18),
                            { ImageColor3 = Color3.fromRGB(255, 255, 255), ImageTransparency = 0.35 }
                        )):Play()
                    end
                    if h then
                        (TweenService:Create(
                            h,
                            TweenInfo.new(0.18),
                            { BackgroundTransparency = 1, Size = UDim2.new(0, 0, 0.7, 0) }
                        )):Play()
                    end
                end
            end
            for d, f in pairs(tabContainers) do
