        local function stripLabelText(c)
            if not c then
                return ""
            end
            return ((((tostring(c)):gsub("<[^>]+>", "")):gsub("%s*%+", "")):gsub("%s*%b()", "")):gsub(
                "^%s*(.-)%s*$",
                "%1"
            )
        end
        function resolveTabNameFromInstance(c)
            local d = c
            while d and (d ~= contentFolder and (d ~= screenGui and d ~= game)) do
                if tabByScroll and tabByScroll[d] then
                    return tabByScroll[d]
                end
                if tabContainers then
                    for a, b in pairs(tabContainers) do
                        if d == b then
                            return a
                        end
                    end
                end
                if groupInfoByContent and (groupInfoByContent[d] and groupInfoByContent[d].parentTab) then
                    return groupInfoByContent[d].parentTab
                end
                d = d.Parent
            end
            return nil
        end
        function registerSearchableFeature(c)
            if not c or not c.name or c.name == "" then
                return
            end
            local d = stripLabelText(c.name)
            if d == "" or d:lower() == "trigger" then
                return
            end
            local f = nil
            if c.container then
                f = resolveTabNameFromInstance(c.container)
            end
            if not f and c.parent then
                f = resolveTabNameFromInstance(c.parent)
            end
            local g = c.tabName or f or currentBuildingTabName or "Home"
            local h = c.sectionName or currentBuildingSectionName or "General"
            local i = {
                name = d,
                rawLabel = c.name,
                tabName = g,
                sectionName = h,
                controlType = c.controlType or "Toggle",
                container = c.container,
                parent = c.parent,
                parentGroup = c.parentGroup,
                isPremium = c.isPremium or isPremiumFeature(c.name),
                keybindName = c.keybindName,
                controlRef = c.controlRef,
                callback = c.callback,
                description = c.description or "",
            }
            table.insert(searchableFeatures, i)
            return i
        end
        function jumpToFeature(c)
            if not c then
                return
            end
            if searchBox then
                searchBox.Text = ""
                searchBox:ReleaseFocus()
            end
            if clearSearchBtn then
                clearSearchBtn.Visible = false
            end
            if searchContainer then
                searchContainer.Visible = false
            end
            local d = c.container or (c.parentGroup and c.parentGroup.container)
            local f = nil
            if d then
                f = resolveTabNameFromInstance(d)
            end
            if not f and c.parent then
                f = resolveTabNameFromInstance(c.parent)
            end
            if not f then
                f = c.tabName
            end
            local g = {
                dashboard = "Home",
                home = "Home",
                esp = "ESP",
                farm = "Farm",
                autofarm = "Farm",
                self = "Self",
                modifiers = "Self",
                combat = "Combat",
                tp = "Teleport",
                teleport = "Teleport",
                teleports = "Teleport",
                visual = "Visuals",
                visuals = "Visuals",
                config = "Config",
                configs = "Config",
                community = "Community",
            }
            if f then
                local c = ((tostring(f)):lower()):gsub("%s+", "")
                if g[c] then
                    f = g[c]
                end
            end
            if not (f and (tabContainers and tabContainers[f])) then
                for a, b in pairs(tabContainers or {}) do
                    if a:lower() == (tostring(f)):lower() then
                        f = a
                        break
                    end
                end
            end
            if not (f and (tabContainers and tabContainers[f])) then
                f = activeTab or "Home"
            end
            if activeTab == f then
                if tabContainers and tabContainers[f] then
                    tabContainers[f].Visible = true
                    tabContainers[f].GroupTransparency = 0
                end
            else
                switchTab(f)
            end
            if d then
                local c = d
                while c and (c ~= contentFolder and (c ~= screenGui and c ~= game)) do
                    if
                        groupInfoByContent
                        and (
                            groupInfoByContent[c]
                            and (groupInfoByContent[c].groupObj and groupInfoByContent[c].groupObj.toggleExpand)
                        )
                    then
                        pcall(function()
                            groupInfoByContent[c].groupObj.toggleExpand(true)
                        end)
                    end
                    c = c.Parent
                end
            end
            if c.parentGroup and c.parentGroup.toggleExpand then
                pcall(function()
                    c.parentGroup.toggleExpand(true)
                end)
            end
            task.spawn(function()
                task.wait(0.12)
                local g = tabScrollByName and (tabScrollByName[f] or tabScrollByName[c.tabName])
                if g and (d and d:IsDescendantOf(g)) then
                    pcall(function()
                        local c = g.AbsolutePosition.Y
                        local f = d.AbsolutePosition.Y
                        local h = g.CanvasPosition.Y
                        local i = (h + (f - c)) - 50
                        g.CanvasPosition = Vector2.new(0, math.max(0, i))
                    end)
                end
                if d and (d.Parent and d.Parent:IsA("ScrollingFrame")) then
                    local c = d.Parent
                    pcall(function()
                        local f = c.AbsolutePosition.Y
                        local g = d.AbsolutePosition.Y
                        local h = c.CanvasPosition.Y
                        local i = (h + (g - f)) - 20
                        c.CanvasPosition = Vector2.new(0, math.max(0, i))
                    end)
                end
                if d then
                    pcall(function()
                        local c = d:FindFirstChildOfClass("UIStroke")
                            or (d:FindFirstChild("VisualFrame") and d.VisualFrame:FindFirstChildOfClass("UIStroke"))
                            or (
                                d:FindFirstChildWhichIsA("Frame")
                                and (d:FindFirstChildWhichIsA("Frame")):FindFirstChildOfClass("UIStroke")
                            )
                        if c then
                            local d = c.Color
                            local f = c.Thickness
                            c.Color = UI.AccentCyan or UI.Accent
                            c.Thickness = 2.2
                            (TweenService:Create(
                                c,
                                TweenInfo.new(1.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                                { Color = d, Thickness = f }
                            )):Play()
                        end
                    end)
                end
            end)
        end
