                elseif j:find(c, 1, true) then
                    n = 4
                elseif k:find(c, 1, true) then
                    n = 5
                elseif l:find(c, 1, true) or m:find(c, 1, true) then
                    n = 6
                end
                if n and not f[h.name .. (":" .. (h.tabName or ""))] then
                    f[h.name .. (":" .. (h.tabName or ""))] = true
                    table.insert(d, { feat = h, score = n })
                end
