            doCancelGen = function()
                if premiumHooks and type(premiumHooks.CancelGen) == "function" then
                    local d = pcall(premiumHooks.CancelGen, localPlayer, cachedGenerators, showNotification)
                    if d then
                        return
                    end
                end
                showNotification("Generator Buff", "Attempting to buff generator...", "info")
                task.spawn(function()
                    local c, d = pcall(function()
                        local c = localPlayer and localPlayer.Character
                        local d = c and c:FindFirstChild("HumanoidRootPart")
                        if not d then
                            showNotification("Generator Buff", "Character HumanoidRootPart not found!", "error")
                            return
                        end
                        local function f(c)
                            if c:IsA("Model") then
                                return c.PrimaryPart or c:FindFirstChildWhichIsA("BasePart")
                            end
                            return c:FindFirstChildWhichIsA("BasePart")
                        end
                        local g = {}
                        local h = workspace:FindFirstChild("Map")
                        local i = {}
                        if h then
                            local c = h:FindFirstChild("Generators")
                            local d = h:FindFirstChild("Gens")
                            if c then
                                table.insert(i, c)
                            end
                            if d then
                                table.insert(i, d)
                            end
                        end
                        for c, d in ipairs(i) do
                            for c, d in ipairs(d:GetChildren()) do
                                if d.Name == "Generator" or string.find(d.Name:lower(), "generator") then
                                    table.insert(g, d)
                                end
                            end
                        end
                        if #g == 0 and type(cachedGenerators) == "table" then
                            for c, d in ipairs(cachedGenerators) do
                                if d and d.Parent then
                                    table.insert(g, d)
                                end
                            end
                        end
                        if #g == 0 then
                            for c, d in ipairs(workspace:GetDescendants()) do
                                if d:IsA("Model") and (d.Name == "Generator" or d.Name:find("Generator")) then
                                    table.insert(g, d)
                                end
                            end
                        end
                        if #g == 0 then
                            showNotification("Generator Buff", "No generators found in map!", "error")
                            return
                        end
                        local j = nil
                        local k = math.huge
                        for c, g in ipairs(g) do
                            local h = f(g)
                            if h then
                                local c = ((h.Position - d.Position)).Magnitude
                                if c < k then
                                    k = c
                                    j = g
                                end
                            end
                        end
                        if not j or k > 30 then
                            local c = j and string.format("%.1f studs", k) or "N/A"
                            showNotification("Generator Buff", "No generator within 30 studs! (" .. (c .. ")"), "error")
                            return
                        end
                        local l = {}
                        for c, d in ipairs(j:GetChildren()) do
                            if
                                string.find(d.Name:lower(), "generatorpoint") or string.find(d.Name:lower(), "point")
                            then
                                table.insert(l, d)
                            end
                        end
                        table.sort(l, function(c, d)
                            return c.Name < d.Name
                        end)
                        local m = game:GetService("ReplicatedStorage")
                        local n = m:FindFirstChild("Remotes")
                        local o = n and n:FindFirstChild("Generator")
                        local p = o and o:FindFirstChild("RepairEvent")
                        if not p then
                            p = m:FindFirstChild("RepairEvent", true)
                        end
                        if not p then
                            for c, d in ipairs(m:GetDescendants()) do
                                if d:IsA("RemoteEvent") and (d.Name == "RepairEvent" or d.Name == "Repair") then
                                    p = d
                                    break
                                end
                            end
                        end
                        for c, d in ipairs(j:GetDescendants()) do
                            if d:IsA("ProximityPrompt") then
                                pcall(function()
                                    fireproximityprompt(d, 0)
                                end)
                            end
                        end
                        local q = #l
                        if p and q >= 2 then
                            if q == 2 then
                                local c = l[1]
                                local d = l[2]
                                p:FireServer(d, true)
                                task.wait(0.2)
                                p:FireServer(c, true)
                                task.wait(0.2)
                                p:FireServer(c, false)
                            else
                                local c = l[q]
                                for d = 1, q - 1, 1 do
                                    local f = l[d]
                                    p:FireServer(f, true)
                                    task.wait(0.2)
                                    p:FireServer(c, true)
                                    task.wait(0.2)
                                    p:FireServer(c, false)
                                    if d < q - 1 then
                                        task.wait(0.2)
                                    end
                                end
                            end
                            showNotification("Generator Buff", "Successfully applied generator buff!", "success")
                        elseif p and q == 1 then
                            p:FireServer(l[1], true)
                            task.wait(0.2)
                            p:FireServer(l[1], false)
                            showNotification("Generator Buff", "Successfully applied generator buff!", "success")
                        else
                            showNotification("Generator Buff", "Generator buff executed!", "success")
                        end
                    end)
                    if not c then
                        showNotification("Generator Buff", "Error: " .. tostring(d), "error")
                    end
                end)
            end
            createButton(tabFarm, "Trigger Generator Buff (Max)", "Trigger", function()
                if doCancelGen then
                    pcall(doCancelGen)
                end
            end, UI.Accent, "CancelGen")
        end
