                local g = c.UserInputType == Enum.UserInputType.Keyboard or f
                local h = c.UserInputType == Enum.UserInputType.MouseButton3
                if g or h then
                    local d = g and c.KeyCode.Name or c.UserInputType.Name
                    if d ~= "Unknown" and d ~= "None" then
