                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end))
        end
        buildCombatTab()
        local function buildTeleportTab()
            activeTPFilter = activeTPFilter or "All"
            do
                local function c(c, d)
                    local f = localPlayer.Character
                    local g = f and f:FindFirstChild("HumanoidRootPart")
                    if not g then
                        showNotification("Teleport", "Character root not found!", "error")
                        return
                    end
                    local h = {}
                    if c == "Generator" then
                        local c = workspace:FindFirstChild("Map")
                        local d = c and c:FindFirstChild("Gens")
                        if d then
                            for c, d in ipairs(d:GetChildren()) do
                                if d.Name == "Generator" or string.find(d.Name:lower(), "generator") then
                                    table.insert(h, d)
                                end
                            end
                        end
                        for c, d in ipairs(cachedGenerators) do
                            if d and (d.Parent and not table.find(h, d)) then
                                table.insert(h, d)
                            end
                        end
                        if #h == 0 then
                            for c, d in ipairs(workspace:GetDescendants()) do
                                if d.Name == "Generator" then
                                    table.insert(h, d)
                                end
                            end
                        end
                    elseif c == "Hook" then
                        for c, d in ipairs(cachedHooks) do
                            if d and d.Parent then
                                table.insert(h, d)
                            end
                        end
                        if #h == 0 then
                            for c, d in ipairs(workspace:GetDescendants()) do
                                if d.Name == "Hook" or (d.Name:lower()):find("hook") then
                                    table.insert(h, d)
                                end
                            end
                        end
                    elseif c == "Gate" then
