                                g = Color3.fromHSV(c, 1, 1)
                            end
                            for c, d in ipairs(h:GetDescendants()) do
                                if d:IsA("Light") then
                                    d.Color = g
                                    if flashlightEnabled then
                                        if settings.FlashlightEffect == "Ultra Bright" then
                                            flashlightUpdating = true
                                            d.Enabled = true
                                            flashlightUpdating = false
                                            d.Range = 250
                                            d.Brightness = 15
                                        elseif settings.FlashlightEffect == "Strobe" then
                                            flashlightUpdating = true
                                            d.Enabled = f
                                            flashlightUpdating = false
                                        else
                                            if flashlightMode == "Ultra Bright" then
                                                d.Range = 51
                                                d.Brightness = 1
                                            end
                                        end
                                    else
                                        flashlightUpdating = true
                                        d.Enabled = false
                                        flashlightUpdating = false
                                        if flashlightMode == "Ultra Bright" then
                                            d.Range = 51
                                            d.Brightness = 1
                                        end
                                    end
                                elseif d:IsA("Beam") then
                                    d.Color = ColorSequence.new(g)
                                    if flashlightEnabled then
                                        if settings.FlashlightEffect == "Strobe" then
                                            d.Enabled = f
                                        elseif settings.FlashlightEffect == "Ultra Bright" then
                                            d.Enabled = true
                                        end
                                    else
                                        d.Enabled = false
                                    end
                                elseif d:IsA("BasePart") then
                                    local c = d.Name:lower()
                                    if
                                        c:find("beam")
                                        or c:find("light")
                                        or c:find("cone")
                                        or (d.Transparency > 0 and d.Transparency < 1)
                                    then
                                        d.Color = g
                                        if flashlightEnabled then
                                            if settings.FlashlightEffect == "Strobe" then
                                                d.Transparency = f and 0.5 or 1
                                            elseif settings.FlashlightEffect == "Ultra Bright" then
                                                d.Transparency = 0.4
                                            end
                                        else
                                            d.Transparency = 1
                                        end
                                    end
                                end
                            end
                        end
                        flashlightMode = settings.FlashlightEffect
                    end
                end)
            end
        end)
