        function makeResizable(c, d)
            local f = false
            local g = nil
            local h = nil
            local i = nil
            d.InputBegan:Connect(function(d)
                if
                    d.UserInputType == Enum.UserInputType.MouseButton1
                    or d.UserInputType == Enum.UserInputType.Touch
                then
                    f = true
                    g = d.Position
                    h = c.Size
                    d.Changed:Connect(function()
                        if d.UserInputState == Enum.UserInputState.End then
                            f = false
                        end
                    end)
                end
            end)
            d.InputChanged:Connect(function(c)
                if
                    c.UserInputType == Enum.UserInputType.MouseMovement
                    or c.UserInputType == Enum.UserInputType.Touch
                then
                    i = c
                end
            end)
            registerConnection(UserInputService.InputChanged:Connect(function(d)
                if d == i and f then
                    local f = d.Position - g
                    local i = math.clamp(h.X.Offset + f.X, 420, 1000)
                    local j = math.clamp(h.Y.Offset + f.Y, 260, 800)
