        local function getCameraLookPoint()
            local c = workspace.CurrentCamera
            if not c then
                return Vector3.zero
            end
            local d = 0
            local f = 0
            if UserInputService:IsKeyDown(Enum.KeyCode.W) or UserInputService:IsKeyDown(Enum.KeyCode.Up) then
                d = d + 1
            end
            if UserInputService:IsKeyDown(Enum.KeyCode.S) or UserInputService:IsKeyDown(Enum.KeyCode.Down) then
                d = d - 1
            end
            if UserInputService:IsKeyDown(Enum.KeyCode.D) or UserInputService:IsKeyDown(Enum.KeyCode.Right) then
                f = f + 1
            end
            if UserInputService:IsKeyDown(Enum.KeyCode.A) or UserInputService:IsKeyDown(Enum.KeyCode.Left) then
                f = f - 1
            end
            if d == 0 and f == 0 then
                return Vector3.zero
            end
            local g = c.CFrame
            local h = Vector3.new(g.LookVector.X, 0, g.LookVector.Z)
            local i = Vector3.new(g.RightVector.X, 0, g.RightVector.Z)
            if h.Magnitude > 0 then
                h = h.Unit
            end
            if i.Magnitude > 0 then
                i = i.Unit
            end
            local j = (h * d) + (i * f)
            return j.Magnitude > 0 and j.Unit or Vector3.zero
        end
        registerConnection(RunService.PreSimulation:Connect(function(c)
            if not activeLoop then
                return
            end
            if not settings.NoTurnSpeedLoss then
                return
            end
            if settings.AutoMoonwalk then
                return
            end
            local d = localPlayer.Character
            if not d then
                return
            end
            local f = d:FindFirstChild("HumanoidRootPart")
            local g = d:FindFirstChildOfClass("Humanoid")
            if not f or not g or g.Health <= 0 then
                return
            end
            local h = getCameraLookPoint()
            local i = h.Magnitude > 0.05
            if i then
                g.AutoRotate = false
                g:Move(h, false)
                local i = d:GetAttribute("speedboost") or 1
                local j = g.WalkSpeed * i
                local k = f.AssemblyLinearVelocity.Y
                f.AssemblyLinearVelocity = Vector3.new(h.X * j, k, h.Z * j)
                local l = f.CFrame.LookVector
                local m = (Vector3.new(l.X, 0, l.Z)).Unit
                local n = m:Dot(h)
                if n < 0.999 then
                    local d = math.atan2(-h.X, -h.Z)
                    local g = math.atan2(-m.X, -m.Z)
                    local i = ((d - g) + math.pi) % (2 * math.pi) - math.pi
                    local j = math.clamp(26 * (c or 0.0166), 0, 1)
                    local k = g + (i * j)
                    local l = f.Position
                    f.CFrame = CFrame.new(l) * CFrame.Angles(0, k, 0)
                end
            else
                g.AutoRotate = true
                g:Move(Vector3.zero, false)
            end
        end))
