                Cyan = Color3.fromRGB(0, 240, 255),
                Red = Color3.fromRGB(255, 50, 50),
                Green = Color3.fromRGB(50, 255, 50),
                Yellow = Color3.fromRGB(255, 255, 50),
                Purple = Color3.fromRGB(170, 80, 255),
                Orange = Color3.fromRGB(255, 125, 0),
                Pink = Color3.fromRGB(255, 100, 200),
                White = Color3.fromRGB(255, 255, 255),
                Blue = Color3.fromRGB(0, 100, 255),
            }
            local d = { gui = nil, frame = nil, corners = {} }
            setupTargetBoxGui = function()
                if d.gui and d.gui.Parent then
                    return
                end
                local c = Instance.new("ScreenGui")
                c.Name = "VD_SilentAimTargetGui"
                c.ResetOnSpawn = false
                c.IgnoreGuiInset = true
                c.DisplayOrder = 999
                c.Parent = guiParent
                d.gui = c
                local f = Instance.new("Frame")
                f.Name = "TargetBox"
                f.BackgroundTransparency = 1
                f.BorderSizePixel = 0
                f.Visible = false
                f.Parent = c
                d.frame = f
                local g = 14
                local h = 2.5
                local function i(c, d, g, h)
                    local i = Instance.new("Frame")
                    i.Name = c
                    i.AnchorPoint = d
                    i.Position = g
                    i.Size = h
                    i.BorderSizePixel = 0
                    i.BackgroundColor3 = Color3.fromRGB(255, 50, 50)
                    i.Parent = f
                    return i
                end
                d.corners = {
                    TL_H = i("TL_H", Vector2.new(0, 0), UDim2.new(0, -1, 0, -1), UDim2.new(0, g, 0, h)),
                    TL_V = i("TL_V", Vector2.new(0, 0), UDim2.new(0, -1, 0, -1), UDim2.new(0, h, 0, g)),
                    TR_H = i("TR_H", Vector2.new(1, 0), UDim2.new(1, 1, 0, -1), UDim2.new(0, g, 0, h)),
                    TR_V = i("TR_V", Vector2.new(1, 0), UDim2.new(1, 1, 0, -1), UDim2.new(0, h, 0, g)),
                    BL_H = i("BL_H", Vector2.new(0, 1), UDim2.new(0, -1, 1, 1), UDim2.new(0, g, 0, h)),
                    BL_V = i("BL_V", Vector2.new(0, 1), UDim2.new(0, -1, 1, 1), UDim2.new(0, h, 0, g)),
                    BR_H = i("BR_H", Vector2.new(1, 1), UDim2.new(1, 1, 1, 1), UDim2.new(0, g, 0, h)),
                    BR_V = i("BR_V", Vector2.new(1, 1), UDim2.new(1, 1, 1, 1), UDim2.new(0, h, 0, g)),
                }
            end
            getSilentAimTarget = function()
                if not isPremium() then
                    return nil, nil
                end
                local c = localPlayer.Character
                local d = workspace.CurrentCamera
                if not d or not c then
                    return nil, nil
                end
                local f = d.ViewportSize / 2
                local g = nil
                local h = math.huge
                local i = nil
                local j = settings.SpearSilentAim
                    and (settings.SpearSilentAim.Enabled and settings.SpearSilentAim.TargetHighlightEnabled)
                local k = settings.RevolverSilentAim
                    and (settings.RevolverSilentAim.Enabled and settings.RevolverSilentAim.TargetHighlightEnabled)
                if not j and not k then
                    return nil, nil
                end
                local l = nil
                pcall(function()
                    for c, d in ipairs(c:GetChildren()) do
                        if d:IsA("Tool") or d:IsA("Model") then
                            local c = d.Name:lower()
                            if
                                c:find("twist")
                                or c:find("fate")
                                or c:find("revolver")
                                or d:FindFirstChild("Right Arm")
                                or d:FindFirstChild("gun", true)
                            then
                                l = "Twist of Fate"
                                break
                            elseif c:find("spear") or c:find("veil") then
                                l = "Veil Spear"
                                break
                            end
                        end
                    end
                end)
                local m = nil
                if (l == "Twist of Fate" or k) and not j then
                    m = "Revolver"
                elseif l == "Twist of Fate" and k then
                    m = "Revolver"
                elseif (l == "Veil Spear" or j) and not k then
                    m = "Spear"
                else
                    if j then
                        m = "Spear"
                    elseif k then
                        m = "Revolver"
                    end
                end
                if not m then
                    return nil, nil
                end
                local n = (m == "Spear") and (settings.SpearSilentAim.FOVRadius or 240)
                    or (settings.RevolverSilentAim.FOVRadius or 200)
                local o = (m == "Spear") and "Both Teams" or (settings.RevolverSilentAim.Target or "Both Teams")
                local p = {}
                for c, g in ipairs(Players:GetPlayers()) do
                    if g ~= localPlayer and (g.Character and g.Character:IsA("Model")) then
                        local c = g.Team and g.Team.Name or ""
                        local h = (m == "Spear")
                            or (o == "Both Teams")
                            or (o == "Survivors" and c == "Survivors")
                            or (o == "Killer" and c == "Killer")
                        if h then
                            local c = g.Character
                            local h = c:FindFirstChild("HumanoidRootPart")
                                or c:FindFirstChild(targetPartName)
                                or c.PrimaryPart
                            local i = c:FindFirstChildOfClass("Humanoid")
                            if h and (i and i.Health > 0) then
                                local j, k = d:WorldToViewportPoint(h.Position)
                                if k and j.Z > 0 then
                                    local d = ((Vector2.new(j.X, j.Y) - f)).Magnitude
                                    if d <= n then
                                        table.insert(p, {
                                            player = g,
                                            character = c,
                                            part = h,
                                            dist = d,
                                            health = i.Health,
                                            maxHealth = i.MaxHealth or 100,
                                        })
                                    end
                                end
                            end
                        end
                    end
                end
                local r = (m == "Spear") and (settings.SpearSilentAim.Priority or "Nearest")
                    or (settings.RevolverSilentAim.Priority or "Nearest")
                local s = sortCandidatesByPriority(p, r, n)
                if s then
                    g = s.character
                    i = m
                end
                return g, i
            end
            get2DBoundingBox = function(c)
                local d = workspace.CurrentCamera
                if not d or not c then
                    return nil
                end
                local f = c:FindFirstChild("Head")
                local g = c:FindFirstChild("HumanoidRootPart") or c.PrimaryPart
                if not g then
                    return nil
                end
                local h = f and (f.Position + Vector3.new(0, 0.7, 0)) or (g.Position + Vector3.new(0, 2.2, 0))
                local i = g.Position - Vector3.new(0, 2.8, 0)
                local j, k = d:WorldToViewportPoint(h)
                local l, m = d:WorldToViewportPoint(i)
                local n, o = d:WorldToViewportPoint(g.Position)
                if not o or n.Z <= 0 then
                    return nil
                end
                local p = math.abs(l.Y - j.Y)
                local q = math.clamp(p * 0.6, 12, 350)
                if p < 6 then
                    return nil
                end
                return n.X - (q / 2), j.Y, q, p
            end
            updateSilentAimTargetHighlight = function()
                local f = settings.SpearSilentAim and (settings.SpearSilentAim.Enabled and isPremium())
                local g = settings.RevolverSilentAim and (settings.RevolverSilentAim.Enabled and isPremium())
                if not f and not g then
                    if d.frame and d.frame.Visible then
                        d.frame.Visible = false
                    end
                    return
                end
                setupTargetBoxGui()
                local h, i = nil, nil
                pcall(function()
                    h, i = getSilentAimTarget()
                end)
                if h and (i and d.frame) then
                    local f, g, j, k = get2DBoundingBox(h)
                    if f and (g and (j and k)) then
                        local h = (i == "Spear") and settings.SpearSilentAim or settings.RevolverSilentAim
                        local l = h.TargetHighlightColor or (i == "Spear" and "Red" or "Cyan")
                        local m = c[l] or (i == "Spear" and Color3.fromRGB(255, 50, 50) or Color3.fromRGB(0, 240, 255))
                        d.frame.Position = UDim2.new(0, f, 0, g)
                        d.frame.Size = UDim2.new(0, j, 0, k)
                        d.frame.BackgroundTransparency = 1
                        local n = math.clamp(math.floor(j * 0.25), 6, 16)
                        local o = d.corners
                        if o.TL_H then
                            o.TL_H.Size = UDim2.new(0, n, 0, 2.5)
                        end
                        if o.TR_H then
                            o.TR_H.Size = UDim2.new(0, n, 0, 2.5)
                        end
                        if o.BL_H then
                            o.BL_H.Size = UDim2.new(0, n, 0, 2.5)
                        end
                        if o.BR_H then
                            o.BR_H.Size = UDim2.new(0, n, 0, 2.5)
                        end
                        if o.TL_V then
                            o.TL_V.Size = UDim2.new(0, 2.5, 0, n)
                        end
                        if o.TR_V then
                            o.TR_V.Size = UDim2.new(0, 2.5, 0, n)
                        end
                        if o.BL_V then
                            o.BL_V.Size = UDim2.new(0, 2.5, 0, n)
                        end
                        if o.BR_V then
                            o.BR_V.Size = UDim2.new(0, 2.5, 0, n)
                        end
                        for c, d in pairs(o) do
                            if d then
                                d.BackgroundColor3 = m
                                d.BackgroundTransparency = 0
                            end
                        end
                        d.frame.Visible = true
                        return
                    end
                end
                if d.frame and d.frame.Visible then
                    d.frame.Visible = false
                end
            end
            registerConnection(RunService.RenderStepped:Connect(function()
                if updateSilentAimTargetHighlight then
                    updateSilentAimTargetHighlight()
                end
            end))
        end)()
    end)(...)
end)(...)
